      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-8098-5",
      "justification": "A major European survey conducted by Eurofound across 35 European countries in 2015, capturing detailed individual-level data on working conditions, exposure to physical and psychosocial health risks, occupational safety, and overall health and well-being at work."
    },
    {
      "title": "Second European Survey of Enterprises on New and Emerging Risks, 2014 (ESENER-2)",
      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-7808-1",
      "justification": "A establishment-level survey carried out by EU-OSHA in 2014 across 36 European nations, measuring occupational safety and health management, workplace risk assessments, and health risk mitigation measures in workplaces."
    },
    {
      "title": "Third European Survey of Enterprises on New and Emerging Risks, 2019 (ESENER-3)",
      "url_or_doi": "https://doi.org/10.5255/UKDA-SN-8690-1",
      "justification": "Conducted by EU-OSHA in 2019 across European countries, this dataset examines occupational health and safety management practices, including psychosocial risk prevention, workplace ergonomics, and safety procedures."
    },
    {
      "title": "Eurostat - European Statistics on Accidents at Work (ESAW)",
      "url_or_doi": "https://ec.europa.eu/eurostat/cache/metadata/en/hsw_acc_work_esms.htm",
      "justification": "Eurostat's harmonized statistical dataset providing standardized statistics on fatal and non-fatal occupational accidents and work-related health problems across European Union member states and partner countries throughout the 2010s."
    }
  ]
